import React, { useEffect, useMemo, useRef, useState } from "react";
import "./Home.css";
import { Link } from "react-router-dom";
import api from "../../api";
import ImgHead from "../../assets/bishopimage.png";
import DefaultThumb from "../../assets/BishopRobertsonTVLogo.png";
import HomeBanner from "../../assets/brtv-home-banner.png";

const CHANNEL_ID = "gworrdns";

/* =========================
   UTILITIES
========================= */
const absUrl = (u) => {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  const base = (api?.defaults?.baseURL || "").replace(/\/api\/?$/, "");
  return u?.startsWith("/") ? `${base}${u}` : `${base}/${u}`;
};

async function safeGet(path, opts = {}) {
  try {
    const res = await api.get(path, {
      ...opts,
      validateStatus: () => true,
    });
    return {
      ok: res.status >= 200 && res.status < 300,
      data: res.data,
    };
  } catch {
    return { ok: false, data: null };
  }
}

function normalizeItems(data) {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  return data.items || data.videos || data.rows || [];
}

/* =========================
   HOME DEFAULTS
========================= */
const HOME_DEFAULTS = {
  hero: { title: "", sub: "", cta_text: "", cta_href: "" },
  join: { title: "", sub: "" },
  watch_more: { title: "", sub: "" },
  about: { name: "", text: "" },
  extra_sections: [],
};

/* =========================
   MAIN HOME
========================= */
export default function Home() {
  const [model, setModel] = useState(HOME_DEFAULTS);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;

    (async () => {
      setLoading(true);

      const res = await safeGet("/pages/home");

      const data =
        res.data?.page?.content_json || res.data?.content_json || null;

      if (!alive) return;

      setModel(data || HOME_DEFAULTS);
      setLoading(false);
    })();

    return () => (alive = false);
  }, []);

  return (
    <main className="home-root">
      <Hero model={model.hero} loading={loading} />
      <FeaturedHighlight />
      <LatestTeaching />
      <AboutSection model={model.about} />
      <Spacer />
    </main>
  );
}

/* =========================
   HERO
========================= */
function Hero({ model }) {
  const m = model || {};
  const bg = absUrl(m.background_url) || HomeBanner;

  return (
    <section className="hero-section" style={{ backgroundImage: `url(${bg})` }}>
      <div className="hero-content">
        <h1>{m.title}</h1>
        <p>{m.sub}</p>

        <Link to={m.cta_href || "/catalog"} className="hero-cta">
          {m.cta_text || "Start Watching"}
        </Link>
      </div>
    </section>
  );
}

/* =========================
   FEATURED LIVE
========================= */
function FeaturedHighlight() {
  const [live, setLive] = useState(false);

  useEffect(() => {
    let alive = true;

    (async () => {
      const res = await safeGet(`/streamcontrol/${CHANNEL_ID}/next-live`);
      if (!alive) return;

      setLive(res.data?.is_live || false);
    })();

    return () => (alive = false);
  }, []);

  return (
    <section className="featured-section">
      <h2>Live Stream</h2>
      {live ? <div>LIVE NOW</div> : <div>Offline</div>}
    </section>
  );
}

/* =========================
   LATEST TEACHING (FIXED)
========================= */
function LatestTeaching() {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;

    (async () => {
      setLoading(true);

      const res = await safeGet("/public/videos", {
        params: { limit: 12 },
      });

      let items = normalizeItems(res.data);

      items = items.sort(
        (a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0),
      );

      if (!alive) return;

      setVideos(items);
      setLoading(false);
    })();

    return () => (alive = false);
  }, []);

  return (
    <section className="latest-section">
      <h2>Latest Teaching</h2>

      {loading ? (
        <div>Loading...</div>
      ) : (
        <div className="latest-grid">
          {videos.map((v) => (
            <Link key={v.id} to={`/watch/${v.id}`}>
              <img src={absUrl(v.thumbnail_url) || DefaultThumb} />
              <h4>{v.title}</h4>
            </Link>
          ))}
        </div>
      )}
    </section>
  );
}

/* =========================
   ABOUT
========================= */
function AboutSection({ model }) {
  const m = model || {};

  return (
    <section className="about-section">
      <img src={ImgHead} alt="Bishop" />
      <div>
        <h4>{m.name}</h4>
        <p>{m.text}</p>
      </div>
    </section>
  );
}

/* =========================
   SPACER
========================= */
function Spacer() {
  return <div style={{ height: 40 }} />;
}
